run_lassocox <- function(...) {
  do.call(lassocox, list(...))
}

get_kv <- function(df, key_col, val_col, key) {
  idx <- which(df[[key_col]] == key)
  if (length(idx) == 0) return(NA_character_)
  as.character(df[[val_col]][idx[1]])
}

# Pure base-R Breslow partial log-likelihood, gradient, and Newton-Raphson solver
breslow_loglik_grad_hess <- function(beta, X, time, status) {
  X <- as.matrix(X)
  p <- ncol(X)
  eta <- as.numeric(X %*% beta)
  exp_eta <- exp(eta)
  utimes <- sort(unique(time[status == 1]))
  loglik <- 0
  grad <- numeric(p)
  hess <- matrix(0, nrow = p, ncol = p)
  for (t_k in utimes) {
    d_idx <- which(time == t_k & status == 1)
    r_idx <- which(time >= t_k)
    d_k <- length(d_idx)
    w_r <- exp_eta[r_idx]
    S0 <- sum(w_r)
    Xr <- X[r_idx, , drop = FALSE]
    S1 <- as.numeric(crossprod(Xr, w_r))
    x_bar <- S1 / S0
    loglik <- loglik + sum(eta[d_idx]) - d_k * log(S0)
    grad <- grad + colSums(X[d_idx, , drop = FALSE]) - d_k * x_bar
    Xw <- sweep(Xr, 1, sqrt(w_r / S0), "*")
    V_k <- crossprod(Xw) - tcrossprod(x_bar)
    hess <- hess - d_k * V_k
  }
  list(loglik = loglik, grad = grad, info = -hess)
}

breslow_newton_fit <- function(X, time, status, max_iter = 50L, tol = 1e-11) {
  X <- as.matrix(X)
  p <- ncol(X)
  beta <- numeric(p)
  for (it in seq_len(max_iter)) {
    res <- breslow_loglik_grad_hess(beta, X, time, status)
    step <- solve(res$info, res$grad)
    beta <- beta + step
    if (max(abs(step)) < tol) break
  }
  final <- breslow_loglik_grad_hess(beta, X, time, status)
  list(coefficients = beta, loglik = final$loglik, aic = -2 * final$loglik + 2 * p)
}

harrell_cindex_base <- function(time, status, risk_scores) {
  n <- length(time)
  conc <- 0
  disc <- 0
  tied_r <- 0
  for (i in seq_len(n)) {
    if (status[i] != 1) next
    for (j in seq_len(n)) {
      if (i == j) next
      if (time[i] < time[j] || (time[i] == time[j] && status[j] == 0)) {
        if (risk_scores[i] > risk_scores[j]) conc <- conc + 1
        else if (risk_scores[i] < risk_scores[j]) disc <- disc + 1
        else tied_r <- tied_r + 1
      }
    }
  }
  (conc + 0.5 * tied_r) / (conc + disc + tied_r)
}

# ==============================================================================
# 1. Hand-Calculable & Independent Oracle Tests (C01-C22)
# ==============================================================================
test_that("C01-C22: modelSummary, coefficients, performance, variableImportance, modelComparison, encoding, and reproducibility match independent oracles", {
  set.seed(20261028)
  n <- 30L
  x1 <- round(seq(-1.45, 1.45, length.out = n), 3)
  x2 <- rep(c(0, 1), length.out = n)
  x3 <- round(sin(seq_len(n)), 3)
  lin <- 0.8 * x1 + 0.6 * x2
  time <- round(rexp(n, rate = 0.08 * exp(lin)) + 0.5, 2)
  status <- ifelse(seq_len(n) %% 3 == 0, 0L, 1L)
  df <- data.frame(
    time = c(time, 12.0, 18.0),
    status = factor(c(ifelse(status == 1L, "Dead", "Alive"), "Dead", "Alive"),
                    levels = c("Alive", "Dead")),
    x1 = c(x1, NA, 0.5),
    x2 = factor(c(ifelse(x2 == 1L, "High", "Low"), "High", "Low"),
                levels = c("Low", "High")),
    x3 = c(x3, 0.2, NA),
    const_num = rep(7, n + 2L),
    stringsAsFactors = FALSE
  )

  res <- run_lassocox(
    data = df, elapsedtime = "time", outcome = "status",
    outcomeLevel = "Dead", censorLevel = "Alive",
    explanatory = c("x1", "x2", "x3", "const_num"),
    lambda = "lambda.min", nfolds = 5, standardize = TRUE, random_seed = 101,
    showVariableImportance = TRUE, showModelComparison = TRUE,
    showEncoding = TRUE, showReproducibility = TRUE
  )

  ms <- res$modelSummary$asDF
  expect_equal(as.numeric(get_kv(ms, "statistic", "value", "Encoded Predictor Columns")), 3)
  expect_equal(as.numeric(get_kv(ms, "statistic", "value", "Sample Size")), 30)
  expect_equal(as.numeric(get_kv(ms, "statistic", "value", "Number of Events")), 20)
  expect_equal(get_kv(ms, "statistic", "value", "Censoring Rate"), "33.3%")
  expect_equal(as.numeric(get_kv(ms, "statistic", "value", "Rows Excluded (Missing Data)")), 2)
  expect_equal(as.numeric(get_kv(ms, "statistic", "value", "Original Candidate Predictors")), 4)

  X <- cbind(x1 = x1, x2High = x2, x3 = x3)
  y <- survival::Surv(time, status)
  set.seed(101)
  ev <- which(status == 1L)
  ce <- which(status == 0L)
  foldid <- integer(n)
  foldid[ev] <- sample(rep(1:5, length.out = length(ev)))
  foldid[ce] <- sample(rep(1:5, length.out = length(ce)))
  cv_fit <- glmnet::cv.glmnet(X, y, family = "cox", cox.ties = "breslow", alpha = 1, foldid = foldid, standardize = TRUE)
  beta <- as.numeric(coef(cv_fit, s = "lambda.min"))
  names(beta) <- colnames(X)
  sel <- which(abs(beta) > 1e-8)

  # KKT stationarity check against pure base-R Breslow gradient
  xm <- colMeans(X)
  wj <- sqrt(colMeans(sweep(X, 2, xm, "-")^2))
  b_res <- breslow_loglik_grad_hess(beta, X, time, status)
  scaled_grad <- (b_res$grad / n) / wj
  expect_lt(max(abs(scaled_grad[sel] - cv_fit$lambda.min * sign(beta[sel]))), 1e-4)

  # Compare against independent ncvreg::ncvsurv when installed
  if (requireNamespace("ncvreg", quietly = TRUE)) {
    fit_ncv <- ncvreg::ncvsurv(X, y, penalty = "lasso", lambda = cv_fit$lambda, eps = 1e-10)
    b_ncv <- as.numeric(coef(fit_ncv, lambda = cv_fit$lambda.min))
    names(b_ncv) <- colnames(X)
    coef_df <- res$coefficients$asDF
    expect_lt(max(abs(coef_df$coefficient - b_ncv[coef_df$variable])), 1e-3)
  }

  # Compare Apparent C-index against pure base-R pairwise concordance
  eta <- as.numeric(X[, sel, drop = FALSE] %*% beta[sel])
  c_base <- harrell_cindex_base(time, status, eta)
  j_c <- as.numeric(get_kv(res$performance$asDF, "metric", "value", "Apparent C-index"))
  expect_equal(j_c, round(c_base, 3))

  # Compare Model Comparison against pure base-R Breslow Newton-Raphson solver
  mc <- res$modelComparison$asDF
  nr_sel <- breslow_newton_fit(X[, sel, drop = FALSE], time, status)
  nr_full <- breslow_newton_fit(X, time, status)
  expect_equal(mc$aic[1], nr_sel$aic, tolerance = 1e-7)
  expect_equal(mc$log_likelihood[1], nr_sel$loglik, tolerance = 1e-7)
  expect_equal(mc$aic[2], nr_full$aic, tolerance = 1e-7)
  expect_equal(mc$log_likelihood[2], nr_full$loglik, tolerance = 1e-7)
})

