# 2. Mathematical Properties & Invariances (EXEC-PROP)
# ==============================================================================
test_that("C13 & C15: Time rescaling invariance and predictor scaling equivariance under standardize=TRUE", {
  set.seed(20261028)
  n <- 40L
  x1 <- rnorm(n)
  x2 <- rnorm(n)
  time <- rexp(n, rate = 0.1 * exp(0.9 * x1 - 0.5 * x2)) + 0.5
  status <- factor(ifelse(seq_len(n) %% 4 == 0, "Alive", "Dead"), levels = c("Alive", "Dead"))
  df <- data.frame(
    time_m = time,
    time_d = time * 30.4375,
    status = status,
    x1 = x1,
    x1_x10 = x1 * 10,
    x2 = x2
  )

  res_m <- run_lassocox(data = df, elapsedtime = "time_m", outcome = "status",
                        outcomeLevel = "Dead", censorLevel = "Alive",
                        explanatory = c("x1", "x2"), lambda = "lambda.min",
                        standardize = TRUE, random_seed = 77, showVariableImportance = TRUE)
  res_d <- run_lassocox(data = df, elapsedtime = "time_d", outcome = "status",
                        outcomeLevel = "Dead", censorLevel = "Alive",
                        explanatory = c("x1", "x2"), lambda = "lambda.min",
                        standardize = TRUE, random_seed = 77, showVariableImportance = TRUE)
  expect_equal(res_m$coefficients$asDF$coefficient, res_d$coefficients$asDF$coefficient, tolerance = 1e-12)

  res_x10 <- run_lassocox(data = df, elapsedtime = "time_m", outcome = "status",
                          outcomeLevel = "Dead", censorLevel = "Alive",
                          explanatory = c("x1_x10", "x2"), lambda = "lambda.min",
                          standardize = TRUE, random_seed = 77, showVariableImportance = TRUE)
  b1 <- res_m$coefficients$asDF$coefficient[res_m$coefficients$asDF$variable == "x1"]
  b1_10 <- res_x10$coefficients$asDF$coefficient[res_x10$coefficients$asDF$variable == "x1_x10"]
  expect_equal(b1, 10 * b1_10, tolerance = 1e-10)

  imp1 <- res_m$variableImportance$asDF$importance_score[res_m$variableImportance$asDF$variable == "x1"]
  imp1_10 <- res_x10$variableImportance$asDF$importance_score[res_x10$variableImportance$asDF$variable == "x1_x10"]
  expect_equal(imp1, imp1_10, tolerance = 1e-10)
})

