test_that("VAL-lassocox-01: suitabilityReport Multicollinearity Check 5 must not list masked within-factor dummy pairs with fabricated r=0.00 or report Max |r|=0.00 for a single factor", {
  set.seed(2026)
  n <- 90L
  grade <- factor(rep(c("G1", "G2", "G3"), each = 30L), levels = c("G1", "G2", "G3"))
  x1 <- as.numeric(grade == "G2") * 1.5 + rnorm(n, sd = 0.8)
  df <- data.frame(
    time = rexp(n, rate = 0.1) + 1,
    status = factor(rep(c("Dead", "Alive"), length.out = n), levels = c("Alive", "Dead")),
    grade = grade,
    x1 = x1
  )
  res <- run_lassocox(data = df, elapsedtime = "time", outcome = "status",
                      outcomeLevel = "Dead", censorLevel = "Alive",
                      explanatory = c("grade", "x1"), suitabilityCheck = TRUE)
  txt <- gsub("\\s+", " ", gsub("<[^>]+>", " ", res$suitabilityReport$content))
  expect_false(grepl("gradeG2 (&|&amp;) gradeG3 \\(r=0\\.00\\)", txt))

  res_single <- run_lassocox(data = df, elapsedtime = "time", outcome = "status",
                             outcomeLevel = "Dead", censorLevel = "Alive",
                             explanatory = c("grade"), suitabilityCheck = TRUE)
  txt_single <- gsub("\\s+", " ", gsub("<[^>]+>", " ", res_single$suitabilityReport$content))
  expect_true(grepl("N/A \\(single", txt_single))
})

test_that("VAL-lassocox-02: .buildRCode matches .stripBackticks() on backticked predictor names and handles jamovi values-attributed time columns", {
  df_bt <- lassocox_breast_cancer[1:80, c("survival_months", "death", "age", "grade")]
  df_bt[["grade ` unusual \" <tag>"]] <- df_bt$grade
  t_fac <- factor(seq_len(nrow(df_bt)))
  attr(t_fac, "values") <- df_bt$survival_months
  df_bt$survival_months <- t_fac

  res_bt <- run_lassocox(
    data = df_bt, elapsedtime = "survival_months", outcome = "death",
    outcomeLevel = "Dead", censorLevel = "Alive",
    explanatory = c("age", "grade ` unusual \" <tag>"),
    lambda = "lambda.min", random_seed = 42, showRCode = TRUE, showReproducibility = TRUE
  )
  code_bt <- gsub("^.*<pre[^>]*><code>|</code></pre>.*$", "", res_bt$rCode$content)
  code_bt <- gsub("&lt;", "<", gsub("&gt;", ">", gsub("&quot;", "\"", gsub("&#39;", "'", code_bt))))
  code_bt <- gsub("&amp;", "&", code_bt)
  env_bt <- new.env(parent = globalenv())
  env_bt$data <- df_bt
  expect_no_error(eval(parse(text = code_bt), envir = env_bt))
  repro_lambda <- as.numeric(get_kv(res_bt$reproducibility$asDF, "item", "value", "Selected lambda"))
  expect_equal(env_bt$lassocox_fit$lambda, repro_lambda, tolerance = 1e-15)
  expect_equal(round(env_bt$lassocox_fit$apparent_c, 3),
               as.numeric(res_bt$performance$asDF$value[1]), tolerance = 1e-12)
})

test_that("VAL-lassocox-03: .makeBinaryRiskGroups splits two distinct risk score values even when median equals maximum risk score", {
  opts <- lassocoxOptions$new(
    elapsedtime = "survival_months", outcome = "death",
    outcomeLevel = "Dead", censorLevel = "Alive",
    explanatory = c("age", "er_status")
  )
  inst <- lassocoxClass$new(options = opts, data = lassocox_breast_cancer[1:30, ])
  scores <- c(rep(-0.8, 12), rep(0, 18))
  groups <- inst$.__enclos_env__$private$.makeBinaryRiskGroups(scores)
  expect_false(is.null(groups))
  expect_equal(length(unique(groups)), 2L)
  expect_equal(as.integer(table(groups)), c(12L, 18L))
})

test_that("VAL-lassocox-04: .cleanData handles factors with explicit NA level (addNA) and factors becoming constant in complete cases", {
  df_addna <- lassocox_breast_cancer[1:80, ]
  df_addna$er_status[1] <- NA
  df_addna$er_na <- addNA(df_addna$er_status)
  expect_no_error(run_lassocox(
    data = df_addna, elapsedtime = "survival_months", outcome = "death",
    outcomeLevel = "Dead", censorLevel = "Alive",
    explanatory = c("age", "er_na")
  ))

  df_cc_fac <- lassocox_breast_cancer[1:80, ]
  df_cc_fac$rare_fac <- factor(c("Rare", rep("Common", 79)), levels = c("Common", "Rare"))
  df_cc_fac$age[1] <- NA_real_
  res_cc <- suppressWarnings(run_lassocox(
    data = df_cc_fac, elapsedtime = "survival_months", outcome = "death",
    outcomeLevel = "Dead", censorLevel = "Alive",
    explanatory = c("age", "tumor_size_cm", "rare_fac"),
    showReproducibility = TRUE
  ))
  expect_equal(res_cc$modelSummary$rowCount, 14L)
  repro_df <- res_cc$reproducibility$asDF
  expect_equal(get_kv(repro_df, "item", "value", "Removed constant design columns"), "rare_fac")
})

test_that("VAL-lassocox-05: Regularization Need status is monotone in EPV and coefficients$importance matches variableImportance$importance_score precision", {
  set.seed(2026)
  df <- data.frame(
    time = rexp(200, 0.1) + 1,
    status = factor(c(rep("Dead", 75), rep("Alive", 125)), levels = c("Alive", "Dead")),
    x1 = rnorm(200), x2 = rnorm(200), x3 = rnorm(200)
  )
  res <- run_lassocox(data = df, elapsedtime = "time", outcome = "status",
                      outcomeLevel = "Dead", censorLevel = "Alive",
                      explanatory = c("x1", "x2", "x3"), suitabilityCheck = TRUE)
  txt <- gsub("\\s+", " ", gsub("<[^>]+>", " ", res$suitabilityReport$content))
  expect_false(grepl("p=3, EPV=25 Moderate dimensionality", txt))
  expect_true(grepl("p=3, EPV=25 Low-dimensional with ample events", txt))

  res_imp <- run_lassocox(
    data = lassocox_breast_cancer, elapsedtime = "survival_months", outcome = "death",
    outcomeLevel = "Dead", censorLevel = "Alive",
    explanatory = c("age", "tumor_size_cm", "grade", "lymph_nodes_positive", "ki67_percent"),
    lambda = "lambda.min", random_seed = 42, showVariableImportance = TRUE
  )
  coef_df <- res_imp$coefficients$asDF
  vi_df <- res_imp$variableImportance$asDF
  expect_equal(coef_df$importance,
               vi_df$importance_score[match(coef_df$variable, vi_df$variable)],
               tolerance = 1e-12)
})

test_that("VAL-lassocox-06: Shipped examples script executes cleanly and vignette/doc metadata align with jamovi/lassocox.a.yaml", {
